#[inductive(update_done)]
fn update_done_inductive(pre: Self, post: Self, rid: ReqId) {
    // The transition changes local_updates[rid] from Applied{ret, idx} to Done{ret, idx}
    // with pre.version_upper_bound > idx
    let applied_idx = pre.local_updates[rid].get_Applied_idx();

    assert forall |node_id| #[trigger] post.combiner.contains_key(node_id)
        implies post.wf_combiner_for_node_id(node_id)
    by {
        assert(pre.wf_combiner_for_node_id(node_id));
        match post.combiner[node_id] {
            CombinerState::Ready => {
                // LogRangeNoNodeId doesn't reference local_updates, trivially preserved
            }
            CombinerState::Placed { queued_ops } => {
                // All entries in queued_ops are Placed (by QueueRidsUpdatePlaced)
                // The changed rid was Applied, so it's not in queued_ops at any position
                // LogRangeMatchesQueue_update_change: rid was Applied (not Placed), so
                // the preservation condition is vacuously true for rid
                LogRangeMatchesQueue_update_change(
                    queued_ops, post.log, 0,
                    post.local_versions[node_id], post.tail,
                    node_id, pre.local_updates, post.local_updates
                );
                // QueueRidsUpdatePlaced: entries are Placed; rid was Applied so not in queue
                assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, 0)) by {
                    assert forall |j| 0 <= j < queued_ops.len() implies {
                        &&& post.local_updates.contains_key(#[trigger] queued_ops[j])
                        &&& post.local_updates[queued_ops[j]].is_Placed()
                    } by {
                        assert(pre.local_updates.contains_key(queued_ops[j]));
                        assert(pre.local_updates[queued_ops[j]].is_Placed());
                        // If queued_ops[j] == rid, then rid would be Placed, but
                        // rid is Applied -- contradiction
                        if queued_ops[j] == rid {
                            assert(false);
                        }
                    };
                };
            }
            CombinerState::LoadedLocalVersion { queued_ops, lversion } => {
                LogRangeMatchesQueue_update_change(
                    queued_ops, post.log, 0, lversion, post.tail,
                    node_id, pre.local_updates, post.local_updates
                );
                // QueueRidsUpdatePlaced: all entries Placed; rid was Applied so not in queue
                assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, 0)) by {
                    assert forall |j| 0 <= j < queued_ops.len() implies {
                        &&& post.local_updates.contains_key(#[trigger] queued_ops[j])
                        &&& post.local_updates[queued_ops[j]].is_Placed()
                    } by {
                        assert(pre.local_updates.contains_key(queued_ops[j]));
                        assert(pre.local_updates[queued_ops[j]].is_Placed());
                        if queued_ops[j] == rid {
                            assert(false);
                        }
                    };
                };
            }
            CombinerState::Loop { queued_ops, idx: loop_idx, lversion, tail } => {
                // LogRangeMatchesQueue: starts at loop_idx, all entries there are Placed.
                // rid was Applied so it can't be at positions >= loop_idx.
                LogRangeMatchesQueue_update_change(
                    queued_ops, post.log, loop_idx, lversion, tail,
                    node_id, pre.local_updates, post.local_updates
                );
                // QueueRidsUpdatePlaced: entries at positions >= loop_idx are Placed.
                // rid was Applied, so queued_ops[j] != rid for j >= loop_idx.
                assert(QueueRidsUpdatePlaced(queued_ops, post.local_updates, loop_idx)) by {
                    assert forall |j| loop_idx <= j < queued_ops.len() implies {
                        &&& post.local_updates.contains_key(#[trigger] queued_ops[j])
                        &&& post.local_updates[queued_ops[j]].is_Placed()
                    } by {
                        assert(pre.local_updates.contains_key(queued_ops[j]));
                        assert(pre.local_updates[queued_ops[j]].is_Placed());
                        if queued_ops[j] == rid {
                            // rid was Applied, not Placed -- contradiction
                            assert(false);
                        }
                    };
                };
                // QueueRidsUpdateDone: Applied->Done, both satisfy is_Applied()||is_Done()
                assert(QueueRidsUpdateDone(queued_ops, post.local_updates, loop_idx)) by {
                    assert forall |j| 0 <= j < loop_idx implies
                        post.local_updates.contains_key(#[trigger] queued_ops[j]) ==> {
                            ||| post.local_updates[queued_ops[j]].is_Applied()
                            ||| post.local_updates[queued_ops[j]].is_Done()
                        }
                    by {
                        if post.local_updates.contains_key(queued_ops[j]) {
                            if queued_ops[j] == rid {
                                // Changed from Applied to Done -- Done is acceptable
                                assert(post.local_updates[queued_ops[j]].is_Done());
                            } else {
                                assert(pre.local_updates.contains_key(queued_ops[j]));
                                assert(
                                    pre.local_updates[queued_ops[j]].is_Applied() ||
                                    pre.local_updates[queued_ops[j]].is_Done()
                                );
                            }
                        }
                    };
                };
            }
            CombinerState::UpdatedVersion { queued_ops, tail } => {
                // QueueRidsUpdateDone covers all entries: Applied->Done is fine
                assert(QueueRidsUpdateDone(queued_ops, post.local_updates, queued_ops.len())) by {
                    assert forall |j| 0 <= j < queued_ops.len() implies
                        post.local_updates.contains_key(#[trigger] queued_ops[j]) ==> {
                            ||| post.local_updates[queued_ops[j]].is_Applied()
                            ||| post.local_updates[queued_ops[j]].is_Done()
                        }
                    by {
                        if post.local_updates.contains_key(queued_ops[j]) {
                            if queued_ops[j] == rid {
                                assert(post.local_updates[queued_ops[j]].is_Done());
                            } else {
                                assert(pre.local_updates.contains_key(queued_ops[j]));
                                assert(
                                    pre.local_updates[queued_ops[j]].is_Applied() ||
                                    pre.local_updates[queued_ops[j]].is_Done()
                                );
                            }
                        }
                    };
                };
            }
        }
    };
}

